def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split core version and pre-release
        if '-' in v_without_build:
            core_part, prerelease_part = v_without_build.split('-', 1)
        else:
            core_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            prerelease = []
            for ident in identifiers:
                if ident.isdigit():
                    prerelease.append((0, int(ident)))
                else:
                    prerelease.append((1, ident))
        else:
            prerelease = None

        return (major, minor, patch, prerelease)

    def sort_key(v):
        major, minor, patch, prerelease = parse_version(v)

        # For sorting: versions with prerelease come before without
        # If prerelease is None, use a high sort value
        if prerelease is None:
            prerelease_key = (1,)  # Sorts after (0, ...)
        else:
            prerelease_key = (0, prerelease)  # Sorts before (1,)

        return (major, minor, patch, prerelease_key)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

